	"github.com/signadot/routesapi/go-routesapi/watched"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/codes"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/IBM/sarama"
)

// Consumer represents a Sarama consumer group consumer
type Consumer struct {
	tracer       trace.Tracer
	logger       log.Factory
	routing      watched.BaselineWatched
	driverStore  *driverStore
	bestETA      *bestETA
	notification notifications.Interface
	ready        chan bool
}

func newConsumer(ctx context.Context, tracerProvider trace.TracerProvider,
	logger log.Factory) *Consumer {
	// create a routesapi baseline watched instance
	// TODO: remove this in case we're not running with Signadot
	//
	// Virtual workloads are excluded: shouldProcess treats "no routing rule"
	// as "the baseline handles it", which is exactly what a virtual workload
	// means.
	routing, err := watched.BaselineWatchedFromEnv(&routesapi.ClientInfo{
		EnableVirtualWorkloads: false,
	})
	if err != nil {
		panic(err)
	}

	tracer := tracerProvider.Tracer("driver")
	return &Consumer{
		tracer:       tracer,
		logger:       logger,
		routing:      routing,
		driverStore:  newDriverStore(tracer, logger),
		bestETA:      newBestETA(tracerProvider, tracer, logger),
		notification: notifications.NewNotificationHandler(tracerProvider, logger),
		ready:        make(chan bool),
	}
}

// Setup is run at the beginning of a new session, before ConsumeClaim
func (consumer *Consumer) Setup(sarama.ConsumerGroupSession) error {
	// Mark the consumer as ready
	close(consumer.ready)
	return nil
}

// Cleanup is run at the end of a session, once all ConsumeClaim goroutines have exited
func (consumer *Consumer) Cleanup(sarama.ConsumerGroupSession) error {
	return nil
}

// ConsumeClaim must start a consumer loop of ConsumerGroupClaim's Messages().
func (consumer *Consumer) ConsumeClaim(session sarama.ConsumerGroupSession, claim sarama.ConsumerGroupClaim) error {
	for {
		select {
		case message, ok := <-claim.Messages():
			if !ok {
				consumer.logger.Bg().Error("message channel was closed")
				return nil
			}
			session.MarkMessage(message, "")
			consumer.processDispatchRequest(message)
		case <-session.Context().Done():
			return nil
		}
	}
}

func (consumer *Consumer) shouldProcess(routingKey string) bool {
	if sbName := config.SignadotSandboxName(); sbName != "" {
		return consumer.routing.RoutesTo(routingKey, sbName)
	}
	return consumer.routing.Get(routingKey) == nil
}

func (consumer *Consumer) processDispatchRequest(msg *sarama.ConsumerMessage) {
	// Extract tracing info from message
	ctx := otel.GetTextMapPropagator().Extract(context.Background(), otelsarama.NewConsumerMessageCarrier(msg))

	// should we process this message?
	routingKey := baggageutils.GetRoutingKey(ctx)

	if !consumer.shouldProcess(routingKey) {
		// this message is not intended for us
		return
	}

	// extract the request context
	reqContext, err := baggageutils.ExtractRequestContext(ctx)
	if err != nil {
		consumer.logger.For(ctx).Error("cannot extract request context from baggage", zap.Error(err))
		return
	}
	if reqContext == nil {
		consumer.logger.For(ctx).Error("empty request context from baggage, ignoring request")
		return
	}

	ctx, span := consumer.tracer.Start(ctx, "ProcessDispatchRequest", trace.WithSpanKind(trace.SpanKindClient))
	span.SetAttributes(
		semconv.MessagingOperationProcess,
		attribute.
			Key("session.id").
			Int(int(reqContext.SessionID)),
	)
	defer span.End()

	// parse the message body
	var dispatchReq DispatchRequest
	err = json.Unmarshal(msg.Value, &dispatchReq)
	if err != nil {
		consumer.logger.For(ctx).Error("error decoding message body")
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	notificationCtx := consumer.notification.NotificationContext(
		reqContext, baggageutils.GetRoutingKey(ctx))
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-finding-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      "Finding an available driver",
	})

	// find availanble drivers
	driverIDs := consumer.driverStore.FindDriverIDs(ctx)

	// populate current driver's locations
	drivers, err := consumer.driverStore.GetDriversLocation(ctx, driverIDs)
	if err != nil {
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// get the driver with the best ETA
	bestDriver, err := consumer.bestETA.Get(ctx, &dispatchReq, drivers)
	if err != nil {
		consumer.logger.For(ctx).Error("error calculating best route", zap.Error(err))
		span.SetStatus(codes.Error, err.Error())
		return
	}

	// send a notification
	consumer.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-dispatched-driver", reqContext.ID),
		Timestamp: time.Now(),
		Context:   notificationCtx,
		Body:      fmt.Sprintf("Driver %s arriving in %s", bestDriver.DriverID, bestDriver.ETA.String()),
	})
}

package location

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"

	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/tracing"
)

// Client is a remote client that implements location.Interface
type Client struct {
	logger   log.Factory
	client   *tracing.HTTPClient
	hostPort string
}

// NewClient creates a new location.Client
func NewClient(tracerProvider trace.TracerProvider, logger log.Factory, addr string) *Client {
	return &Client{
		logger:   logger,
		client:   tracing.NewHTTPClient(tracerProvider),
		hostPort: addr,
	}
}

// Get implements location.Interface#Get as an RPC
func (c *Client) Get(ctx context.Context, locationID int) (*Location, error) {
	c.logger.For(ctx).Info("Getting location", zap.Int("location_id", locationID))

	url := fmt.Sprintf("http://"+c.hostPort+"/location?locationID=%d", locationID)
	var location Location
	if err := c.client.GetJSON(ctx, "/location", url, &location); err != nil {
		return nil, err
	}
	return &location, nil
}

func (c *Client) List(ctx context.Context) ([]Location, error) {
	c.logger.For(ctx).Info("Getting locations")

	url := fmt.Sprintf("http://%s/locations", c.hostPort)
	fmt.Println(url)
	var locations []Location
	if err := c.client.GetJSON(ctx, "/locations", url, &locations); err != nil {
		return nil, err
	}
	return locations, nil
}

func (c *Client) Put(ctx context.Context, location *Location) error {
	c.logger.For(ctx).Info("PUT location", zap.Int64("location_id", location.ID))

	url := fmt.Sprintf("http://%s/location?locationID=%d", c.hostPort, location.ID)
	fmt.Println(url)
	var outLocation Location
	if err := c.putJSON(ctx, url, location, outLocation); err != nil {
		return err
	}
	return nil
}

func (c *Client) putJSON(ctx context.Context, url string, reqIn, respOut interface{}) error {
	d, err := json.Marshal(reqIn)
	if err != nil {
		return err
	}
	req, err := http.NewRequest("PUT", url, bytes.NewBuffer(d))
	req.Header.Add("Content-type", "application/json")
	if err != nil {
		return err
	}
	req = req.WithContext(ctx)

	res, err := c.client.Client.Do(req)
	if err != nil {
		return err
	}

	defer res.Body.Close()

	if res.StatusCode >= 400 {
		body, err := io.ReadAll(res.Body)
		if err != nil {
			return err
		}
		return errors.New(string(body))
	}
	decoder := json.NewDecoder(res.Body)
	return decoder.Decode(respOut)
}

package frontend

import (
	"embed"
	"encoding/json"
	"expvar"
	"fmt"
	"net"
	"net/http"
	"os"
	"path"
	"strconv"
	"time"

	"github.com/prometheus/client_golang/prometheus/promhttp"
	"go.opentelemetry.io/otel/baggage"
	"go.opentelemetry.io/otel/trace"
	"go.uber.org/zap"

	"github.com/signadot/hotrod/pkg/baggageutils"
	"github.com/signadot/hotrod/pkg/config"
	"github.com/signadot/hotrod/pkg/httperr"
	"github.com/signadot/hotrod/pkg/log"
	"github.com/signadot/hotrod/pkg/notifications"
	"github.com/signadot/hotrod/pkg/tracing"
	"github.com/signadot/hotrod/services/location"
)

//go:embed web_assets/*
var assetFS embed.FS

// Server implements hotrod-frontend service
type Server struct {
	addr     string
	basepath string

	tracer       trace.TracerProvider
	logger       log.Factory
	location     location.Interface
	notification notifications.Interface
	dispatcher   *dispatcher
}

// NewServer creates a new frontend.Server
func NewServer(logger log.Factory) *Server {
	// get tracer provider for the frontend
	tracerProvider := tracing.InitOTEL("frontend", logger)

	// get location client
	locationClient := location.NewClient(tracerProvider, logger, config.GetLocationAddr())

	// get notification handler
	notificationHandler := notifications.NewNotificationHandler(tracerProvider, logger)

	// get a dispatcher
	dispatcher := newDispatcher(tracerProvider, logger, locationClient)

	return &Server{
		addr:     net.JoinHostPort("0.0.0.0", config.GetFrontendBindPort()),
		basepath: config.GetFrontendBasepath(),

		tracer:       tracerProvider,
		logger:       logger,
		location:     locationClient,
		notification: notificationHandler,
		dispatcher:   dispatcher,
	}
}

// Run starts the frontend server
func (s *Server) Run() error {
	mux := s.createServeMux()
	s.logger.Bg().Info("Starting", zap.String("address", "http://"+path.Join(s.addr, s.basepath)))
	server := &http.Server{
		Addr:              s.addr,
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
	}
	return server.ListenAndServe()
}

func (s *Server) createServeMux() http.Handler {
	mux := tracing.NewServeMux(true, s.tracer, s.logger)
	p := path.Join("/", s.basepath)
	mux.Handle(path.Join(p, "/dispatch"), http.HandlerFunc(s.dispatch))
	mux.Handle(path.Join(p, "/notifications"), http.HandlerFunc(s.notifications))
	mux.Handle(path.Join(p, "/debug/vars"), expvar.Handler())       // expvar
	mux.Handle(path.Join(p, "/metrics"), promhttp.Handler())        // Prometheus
	mux.Handle(path.Join(p, "/splash"), http.HandlerFunc(s.splash)) // Prometheus
	staticFileServer := http.FileServer(http.FS(assetFS))

	mux.Handle("/web_assets/", http.StripPrefix("", staticFileServer))

	mux.Handle("/", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/" {
			indexContent, err := assetFS.ReadFile("web_assets/index.html")
			if err != nil {
				http.Error(w, "Internal server error", http.StatusInternalServerError)
				return
			}
			w.Header().Set("Content-Type", "text/html; charset=utf-8")
			w.Write(indexContent)
		} else {
			staticFileServer.ServeHTTP(w, r)
		}
	}))
	mux.Handle(path.Join(p, "/healthz"), http.HandlerFunc(func(resp http.ResponseWriter, req *http.Request) {
		s.logger.For(req.Context()).Info("/healthz")
		resp.Write([]byte("ok"))
	}))
	return mux
}

func (s *Server) splash(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	// get all stored locations
	locations, err := s.location.List(ctx)
	if err != nil {
		httperr.HandleError(w, err, http.StatusInternalServerError)
		return
	}

	// load data for the template
	data := struct {
		Locations   []location.Location
		TitleSuffix string
	}{locations, os.Getenv("FRONTEND_TITLE_SUFFIX")}

	s.writeResponse(data, w, r)
}

func (s *Server) dispatch(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))

	// decode request body
	var dispatchReq DispatchRequest
	err := json.NewDecoder(r.Body).Decode(&dispatchReq)
	if httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("error parsing request body", zap.Error(err))
		return
	}

	// get request context
	reqContext := &notifications.RequestContext{
		ID:                dispatchReq.RequestID,
		SessionID:         dispatchReq.SessionID,
		PickupLocationID:  dispatchReq.PickupLocationID,
		DropoffLocationID: dispatchReq.DropoffLocationID,
	}

	// inject the request context into baggage and update the current context
	bag, err := baggageutils.InjectRequestContext(ctx, reqContext)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("cannot inject request context into baggage", zap.Error(err))
		return
	}
	ctx = baggage.ContextWithBaggage(ctx, *bag)

	// send frontend-dispatching-driver notification
	s.logger.For(ctx).Info("Dispatching driver", zap.Any("request", dispatchReq))
	s.notification.Store(ctx, &notifications.Notification{
		ID:        fmt.Sprintf("req-%d-frontend-dispatching-driver", dispatchReq.RequestID),
		Timestamp: time.Now(),
		Context:   s.notification.NotificationContext(reqContext, baggageutils.GetRoutingKey(ctx)),
		Body:      "Processing dispatch driver request",
	})

	// resolve locations
	pickupLoc, dropoffLoc, err := s.dispatcher.ResolveLocations(ctx, &dispatchReq)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("couldn't resolve locations", zap.Error(err))
		return
	}

	// dispatch a driver request
	err = s.dispatcher.DispatchDriver(ctx, &dispatchReq, pickupLoc, dropoffLoc)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("couldn't trigger dispatch request", zap.Error(err))
		return
	}
	s.writeResponse(map[string]interface{}{}, w, r)
}

func (s *Server) notifications(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	s.logger.For(ctx).Info("HTTP request received", zap.String("method", r.Method), zap.Stringer("url", r.URL))
	if err := r.ParseForm(); httperr.HandleError(w, err, http.StatusBadRequest) {
		s.logger.For(ctx).Error("bad request", zap.Error(err))
		return
	}

	sessionIDStr := r.Form.Get("sessionID")
	if sessionIDStr == "" {
		http.Error(w, "Missing required 'sessionID' parameter", http.StatusBadRequest)
		return
	}
	sessionID, err := strconv.Atoi(sessionIDStr)
	if err != nil {
		http.Error(w, "Parameter 'sessionID' is not an integer", http.StatusBadRequest)
		return
	}

	cursorStr := r.Form.Get("cursor")
	if cursorStr == "" {
		http.Error(w, "Missing required 'cursor' parameter", http.StatusBadRequest)
		return
	}
	cursor, err := strconv.Atoi(cursorStr)
	if err != nil {
		http.Error(w, "Parameter 'cursor' is not an integer", http.StatusBadRequest)
		return
	}

	data, err := s.notification.List(ctx, uint(sessionID), cursor)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(ctx).Error("request failed", zap.Error(err))
		return
	}

	s.writeResponse(data, w, r)
}

func (s *Server) writeResponse(response interface{}, w http.ResponseWriter, r *http.Request) {
	data, err := json.Marshal(response)
	if httperr.HandleError(w, err, http.StatusInternalServerError) {
		s.logger.For(r.Context()).Error("cannot marshal response", zap.Error(err))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	w.Write(data)
}

