package driver

import (
	"fmt"
	"math"
	"time"
)

const (
	// farePerMinuteCents is the per-minute rate, in cents ($1.50/minute).
	farePerMinuteCents = 150
	// minFareCents is the minimum fare, in cents ($3.50).
	minFareCents = 350
)

// computeFareCents returns the fare, in cents, for a route with the given ETA.
func computeFareCents(eta time.Duration) int64 {
	cents := int64(math.Round(eta.Minutes() * farePerMinuteCents))
	if cents < minFareCents {
		return minFareCents
	}
	return cents
}

// formatFare formats an amount in cents as a dollar string, e.g. "$3.50".
func formatFare(cents int64) string {
	return fmt.Sprintf("$%d.%02d", cents/100, cents%100)
}
EOF
