	"testing"
	"time"
)

func TestFare(t *testing.T) {
	for _, tc := range []struct {
		eta  time.Duration
		want string
	}{
		{-5 * time.Minute, "$3.50"},
		{0, "$3.50"},
		{time.Minute, "$3.50"},
		{2 * time.Minute, "$3.50"},
		{2*time.Minute + 20*time.Second, "$3.50"},
		{2*time.Minute + 21*time.Second, "$3.53"},
		{4 * time.Minute, "$6.00"},
		{4*time.Minute + 30*time.Second, "$6.75"},
		{100 * time.Minute, "$150.00"},
	} {
		if got := formatFare(computeFareCents(tc.eta)); got != tc.want {
			t.Errorf("eta %v: got %s, want %s", tc.eta, got, tc.want)
		}
	}
}
EOF
