// The driver notification body looks like:
//   "Driver T712345C arriving in 2m3s. Fare: $6.00"

export const parseDriverPlate = (body: string): string | undefined => {
    const match = body.match(/Driver\s+(.*?)\s+arriving/);
    return match ? match[1] : undefined;
}

// Returns the fare in dollars, or undefined if the notification has no fare
// (e.g. it was sent by a driver service that doesn't compute it).
export const parseDriverFare = (body: string): number | undefined => {
    const match = body.match(/Fare:\s*\$(\d+(?:\.\d+)?)/);
    return match ? parseFloat(match[1]) : undefined;
}

export const formatFare = (fare: number) => `$${fare.toFixed(2)}`;
