}
package watched

import (
	"context"
	"fmt"
	"log/slog"

	"github.com/signadot/routesapi/go-routesapi"
	"google.golang.org/protobuf/proto"
)

type BaselineWatched interface {
	// Get returns a workload routing rule associated with
	// the routing key rk for the associated baseline workload.
	Get(rk string) *routesapi.WorkloadRoutingRule

	// Same as Get() but with context handling
	GetWithContext(ctx context.Context, rk string) (*routesapi.WorkloadRoutingRule, error)

	// RoutesTo returns true if traffic destined to the associated
	// baseline workload with routing key rk should be directed to
	// the sandbox named sbName.
	RoutesTo(rk, sbName string) bool

	// Same as RoutesTo() but with context handling
	RoutesToWithContext(ctx context.Context, rk, sbName string) (bool, error)
}

type baselineWatched struct {
	*watched
	baseline *routesapi.BaselineWorkload
}

func NewBaselineWatched(ctx context.Context, cfg *Config, b *routesapi.BaselineWorkload,
	cliInfo *routesapi.ClientInfo) (BaselineWatched, error) {
	bb := proto.Clone(b).(*routesapi.BaselineWorkload)
	w, err := NewWatched(ctx, cfg, &routesapi.WorkloadRoutingRulesRequest{
		BaselineWorkload: bb,
		ClientInfo:       cliInfo,
	})
	if err != nil {
		return nil, err
	}
	return &baselineWatched{
		watched:  w.(*watched),
		baseline: bb,
	}, nil
}

func BaselineWatchedFromEnv(cliInfo *routesapi.ClientInfo) (BaselineWatched, error) {
	baseline, err := BaselineFromEnv()
	if err != nil {
		return nil, fmt.Errorf("could not get baseline from env: %w", err)
	}
	cfg := &Config{
		Addr: GetRouteServerAddr(),
		Log:  slog.Default(),
	}
	apiBaseline := &routesapi.BaselineWorkload{
		Kind:      baseline.Kind,
		Namespace: baseline.Namespace,
		Name:      baseline.Name,
	}
	return NewBaselineWatched(context.Background(), cfg, apiBaseline, cliInfo)
}

func (bw *baselineWatched) Get(rk string) *routesapi.WorkloadRoutingRule {
	return bw.watched.Get(bw.baseline, rk)
}

func (bw *baselineWatched) GetWithContext(ctx context.Context, rk string) (*routesapi.WorkloadRoutingRule, error) {
	return bw.watched.GetWithContext(ctx, bw.baseline, rk)
}

func (bw *baselineWatched) RoutesTo(rk string, sbName string) bool {
	return bw.watched.RoutesTo(bw.baseline, rk, sbName)
}

func (bw *baselineWatched) RoutesToWithContext(ctx context.Context, rk string, sbName string) (bool, error) {
	return bw.watched.RoutesToWithContext(ctx, bw.baseline, rk, sbName)
}
