package main

import (
	"net"

	routesapi "github.com/signadot/routesapi/go-routesapi"
	"google.golang.org/grpc"
)

type srv struct {
	routesapi.UnimplementedRoutesServer
}

func (srv) WatchWorkloadRoutingRules(_ *routesapi.WorkloadRoutingRulesRequest, s routesapi.Routes_WatchWorkloadRoutingRulesServer) error {
	if err := s.Send(&routesapi.WorkloadRoutingRuleOp{Op: routesapi.WatchOp_SYNCED}); err != nil {
		return err
	}
	<-s.Context().Done()
	return nil
}

func main() {
	l, err := net.Listen("tcp", "127.0.0.1:7777")
	if err != nil {
		panic(err)
	}
	g := grpc.NewServer()
	routesapi.RegisterRoutesServer(g, srv{})
	g.Serve(l)
}
EOF
